SELECT
    COALESCE(cancel_reason, '未填写原因') as cancelReason,
    COUNT(*) as cancelCount
FROM restaurant_order
WHERE store_id = #{storeId}
  AND status = 6
  AND created_at >= #{startTime}
  AND created_at <= #{endTime}
GROUP BY cancel_reason
ORDER BY cancelCount DESC

SELECT COALESCE(SUM(CASE WHEN roi.is_gift = 0 THEN roi.total_price ELSE 0 END), 0)
FROM restaurant_order_item roi
         INNER JOIN restaurant_order ro ON roi.order_id = ro.id
         INNER JOIN dish d ON roi.dish_id = d.id
         INNER JOIN dish_category dc ON d.category_id = dc.id
WHERE ro.store_id = #{storeId}
  AND ro.payment_status = 1
  AND ro.status != 6
  AND ro.created_at >= #{startTime}
  AND ro.created_at <= #{endTime}

SELECT COALESCE(SUM(roi.quantity), 0)
FROM restaurant_order_item roi
         INNER JOIN restaurant_order ro ON roi.order_id = ro.id
         INNER JOIN dish d ON roi.dish_id = d.id
         INNER JOIN dish_category dc ON d.category_id = dc.id
WHERE ro.store_id = #{storeId}
  AND ro.payment_status = 1
  AND ro.status != 6
  AND ro.created_at >= #{startTime}
  AND ro.created_at <= #{endTime}
